<script setup lang="ts">
import type { BsControlAdjustmentForm, BsControlReconciliationCopy, BsControlReconciliationView } from '../types/financialAccountsPresentation'
defineProps<{ copy: BsControlReconciliationCopy; view: BsControlReconciliationView; accountLabel: string; actionsLabel: string; saveLabel: string; cancelLabel: string }>()
const date = defineModel<string>('date', { required: true })
const form = defineModel<BsControlAdjustmentForm>('form', { required: true })
const emit = defineEmits<{ adjust: [id: string]; close: []; save: [] }>()
function field<K extends keyof BsControlAdjustmentForm>(key: K, value: BsControlAdjustmentForm[K]) { form.value = { ...form.value, [key]: value } }
</script>
<template>
 <template v-if="view.visible"><BsCard padding="none" overflow="hidden"><BsInline wrap align="end" justify="between" padding="lg"><BsBox><BsHeading id="control-reconciliation-heading" :level="2" size="h3">{{ copy.title }}</BsHeading><BsText size="sm" tone="muted">{{ copy.hint }}</BsText></BsBox><BsFloatingField :label="copy.date"><BsInput id="control-as-of-date" :model-value="date" type="date" @update:model-value="date = String($event ?? '')"/></BsFloatingField></BsInline><BsText v-if="view.loading" role="status" size="sm" tone="muted">{{ copy.loading }}</BsText><BsText v-else-if="view.error" role="alert" tone="danger">{{ view.error }}</BsText><BsDataTable v-else :value="view.rows" data-key="id" :label="copy.title" :columns="[{ key: 'name', header: accountLabel }, { key: 'subledger', field: 'subledger', header: copy.subledger }, { key: 'gl', field: 'gl', header: copy.gl, align: 'end' }, { key: 'balance', field: 'balance', header: copy.balance, align: 'end' }, { key: 'variance', field: 'variance', header: copy.variance, align: 'end' }, { key: 'status', header: copy.status }, { key: 'actions', header: actionsLabel }]"><template #cell-name="{ row }"><BsText>{{ row.name }}</BsText><BsText v-if="row.code" size="xs" tone="muted">{{ row.code }}</BsText></template><template #cell-status="{ row }"><BsStatusBadge :status="row.status" :label="row.statusLabel" :tone="row.tone"/><BsText v-if="row.explanation" size="xs" tone="muted">{{ row.explanation }}</BsText></template><template #cell-actions="{ row }"><BsLink v-if="row.inventoryTo" :to="row.inventoryTo">{{ row.inventoryLabel }}</BsLink><BsButton v-else-if="row.canAdjust" size="sm" @click="emit('adjust', row.id)">{{ copy.adjust }}</BsButton></template></BsDataTable></BsCard>
  <BsRecordActionDialog :visible="view.dialog.visible" :title="copy.adjust" size="md" :dirty="view.dialog.dirty" :pending="view.dialog.pending" :error="view.dialog.error" :submit-label="saveLabel" :cancel-label="cancelLabel" @update:visible="value => { if (!value) emit('close') }" @submit="emit('save')"><BsText size="sm" tone="muted">{{ view.dialog.name }}</BsText><BsFloatingField :label="copy.date"><BsInput :model-value="form.date" type="date" required @update:model-value="field('date', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.counterpart"><BsSelect :model-value="form.counterpartAccountId" :label="copy.counterpart" required :options="view.dialog.accounts" option-label="label" option-value="value" native @update:model-value="field('counterpartAccountId', String($event))"/></BsFloatingField><BsFloatingField :label="copy.side"><BsSelect :model-value="form.controlSide" :label="copy.side" :options="view.dialog.sides" option-label="label" option-value="value" native @update:model-value="field('controlSide', $event as 'debit' | 'credit')"/></BsFloatingField><BsFloatingField :label="copy.amount"><BsInput :model-value="form.amount" inputmode="decimal" required @update:model-value="field('amount', String($event ?? ''))"/></BsFloatingField><BsFloatingField v-for="key in (['description', 'reason', 'reference'] as const)" :key="key" :label="copy[key]"><BsInput :model-value="form[key]" required @update:model-value="field(key, String($event ?? ''))"/></BsFloatingField><BsText size="sm" tone="muted">{{ copy.warning }}</BsText></BsRecordActionDialog>
 </template>
</template>
